#!/usr/bin/env python3
# Round81 B13 blind predictions writer. Assertions on count/id set; no glob deletes.
import json, os
BASE = "/home/hatch/workspace/divination/benchmark/phase3/runs/round81"
BATCHES = os.path.join(BASE, "batches.json")
OUTDIR = os.path.join(BASE, "predictions")
EXPECTED = json.load(open(BATCHES, encoding="utf-8"))["B13"]

P = {}
def add(cid, text, basis, conf, trig):
    P[cid] = {"case_id": cid, "prediction_text": text, "basis": basis,
              "confidence": conf, "trigger": trig}
def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

